import { Block, Text } from "@prototyp/skeletor";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { fetchMedia } from "modules/matrix-client/utils";
import { type FC, useEffect, useState } from "react";
import { Image } from "react-native";
import { Colors, TextSize } from "shared/styles";
import {
  cacheImageWithKey,
  getCachedImagePathByURL,
  isCached,
} from "shared/utils/image-caching";
import { Button } from "../button";

interface Props {
  avatarUrl: string | null | undefined;
  displayName: string | undefined;
  height?: number;
  width?: number;
  borderRadius?: number;
  onPress?: (uri: string) => void;
}

export const UserImage: FC<Props> = ({
  avatarUrl,
  displayName,
  height = 32,
  width = 32,
  borderRadius = 48,
  onPress,
}) => {
  const [uri, setUri] = useState<string | null>(null);
  const textSize = () => {
    if (height < 20) return TextSize.xtiny;
    if (height < 28) return TextSize.tiny;
    if (height < 32) return TextSize.small;
    if (height < 40) return TextSize.base;
    if (height < 48) return TextSize.medium;
    if (height < 56) return TextSize.large;

    return TextSize.xlarge;
  };

  useEffect(() => {
    setUri(null);

    const fetch = async () => {
      if (!avatarUrl) {
        return;
      }

      try {
        if (await isCached(avatarUrl)) {
          setUri(getCachedImagePathByURL(avatarUrl));
          return;
        }
        const url = await fetchMedia({
          url: avatarUrl,
          width,
          height,
          serverUrl:
            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
        });
        if (!url) return;
        await cacheImageWithKey(avatarUrl, url);
        setUri(getCachedImagePathByURL(avatarUrl));
      } catch (e) {
        console.log(e);
      }
    };

    fetch();
  }, [avatarUrl, width, height]);

  if (uri) {
    const image = (
      <Image
        source={{ uri }}
        width={width}
        height={height}
        style={{
          width,
          height,
          borderRadius,
          borderWidth: 2,
          borderColor: Colors.white20,
        }}
      />
    );

    if (onPress) {
      return (
        <Button.Wrapper onPress={() => onPress(uri)}>{image}</Button.Wrapper>
      );
    }

    return image;
  }

  return (
    <Block
      width={width}
      height={height}
      border={{
        borderWidth: 1,
        borderColor: Colors.white20,
        borderRadius,
      }}
      background={Colors.white20}
      align="center"
      justify="center"
    >
      <Text size={textSize()} color={Colors.white50}>
        {displayName?.charAt(0).toUpperCase()}
      </Text>
    </Block>
  );
};

import type { UserProfile } from "@unomed/react-native-matrix-sdk";
import { atomWithStorage } from "jotai/utils";
import { SecureStoreKeys } from "modules/matrix-client/models";
import {
  JotaiStorageBooleanAdapter,
  JotaiStorageJsonAdapter,
  JotaiStorageStringAdapter,
} from "../utils";

const screenLockPin = atomWithStorage<string>(
  SecureStoreKeys.SCREEN_LOCK_PIN,
  "",
  JotaiStorageStringAdapter,
);

const screenLockAttempts = atomWithStorage<string>(
  SecureStoreKeys.SCREEN_LOCK_ATTEMPTS,
  "0",
  JotaiStorageStringAdapter,
);

const hasSeenOnboarding = atomWithStorage<boolean>(
  SecureStoreKeys.HAS_SEEN_ONBOARDING,
  false,
  JotaiStorageBooleanAdapter,
);

const hasRunIdentityConfirmation = atomWithStorage<boolean>(
  SecureStoreKeys.HAS_RUN_IDENTITY_CONFIRMATION,
  false,
  JotaiStorageBooleanAdapter,
);

const cachedProfile = atomWithStorage<UserProfile | null>(
  SecureStoreKeys.USER_PROFILE_CACHE,
  null,
  JotaiStorageJsonAdapter<UserProfile | null>(),
);

export const StorageAtoms = {
  screenLockPin,
  screenLockAttempts,
  hasSeenOnboarding,
  hasRunIdentityConfirmation,
  cachedProfile,
};

