import type { SyncStorage } from "jotai/vanilla/utils/atomWithStorage";
import { MMKV } from "react-native-mmkv";

export const mmkvStorageJotaiAdapter = new MMKV({
  id: "jotai-storage-adapter",
});

export const JotaiStorageJsonAdapter = <T>(): SyncStorage<T> => ({
  getItem: (key: string, initialValue: T): T => {
    const value = mmkvStorageJotaiAdapter.getString(key);
    if (!value) return initialValue;
    try {
      return JSON.parse(value) as T;
    } catch {
      return initialValue;
    }
  },
  setItem: (key: string, value: T) => {
    mmkvStorageJotaiAdapter.set(key, JSON.stringify(value));
  },
  removeItem: (key: string) => {
    mmkvStorageJotaiAdapter.delete(key);
  },
});

export const JotaiStorageStringAdapter: SyncStorage<string> = {
  getItem: (key: string, initialValue: string): string => {
    const value = mmkvStorageJotaiAdapter.getString(key);
    if (!value) return initialValue;
    return value;
  },
  setItem: (key: string, value: string) => {
    mmkvStorageJotaiAdapter.set(key, value);
  },
  removeItem: (key: string) => {
    mmkvStorageJotaiAdapter.delete(key);
  },
};

export const JotaiStorageBooleanAdapter: SyncStorage<boolean> = {
  getItem: (key: string, initialValue: boolean): boolean => {
    const value = mmkvStorageJotaiAdapter.getBoolean(key);
    if (value === undefined) return initialValue;
    return value;
  },
  setItem: (key: string, value: boolean) => {
    mmkvStorageJotaiAdapter.set(key, value);
  },
  removeItem: (key: string) => {
    mmkvStorageJotaiAdapter.delete(key);
  },
};

